// /app/app/mobile-pager.js — phone section pages + bottom dock.
//
// Under PHONE_QUERY every element tagged data-mpage belongs to one page;
// mobile-pager.css hides the others from body[data-mobile-page]. Nothing is
// moved in the DOM, so panels keep their lifecycle and the desktop grid is
// untouched. Containers that hold several pages list all of them
// (data-mpage="draw buy flip").
//
// Swiping sideways anywhere outside a horizontal control steps to the next or
// previous page; the dock tabs jump straight to one. The dock's top strip is a
// condensed Pending summary published by app-reveal-tray; tapping it opens the
// full tray as a sheet above the dock.

const PHONE_QUERY = '(max-width: 768px)';
const PAGES = ['draw', 'buy', 'flip', 'quests', 'craps', 'degenerette', 'more'];
const STORAGE_KEY = 'mobilePager.page';
const EDGE_GUARD_PX = 18;
const AXIS_LOCK_PX = 10;
const COMMIT_FRACTION = 0.22;
const COMMIT_VELOCITY = 0.35; // px per ms
const EDGE_RESISTANCE = 0.28;

const phone = typeof window.matchMedia === 'function'
  ? window.matchMedia(PHONE_QUERY)
  : { matches: false, addEventListener() {} };
const reducedMotion = typeof window.matchMedia === 'function'
  ? window.matchMedia('(prefers-reduced-motion: reduce)')
  : { matches: false };

const body = document.body;
const main = document.querySelector('main');
const dock = document.querySelector('.mpager-dock');
const scrim = document.querySelector('[data-mpager-scrim]');
const pendingButton = dock?.querySelector('[data-mpager-pending]');
const scrollByPage = new Map();
let current = PAGES.includes(body.dataset.mobilePage) ? body.dataset.mobilePage : PAGES[0];
let transition = null;

function pageOf(element) {
  const host = element?.closest?.('[data-mpage]');
  if (!host) return null;
  const pages = host.getAttribute('data-mpage').trim().split(/\s+/);
  return pages.includes(current) ? current : pages[0];
}

function contentTop() {
  return main ? main.getBoundingClientRect().top + window.scrollY : 0;
}

function applyPage(page) {
  scrollByPage.set(current, window.scrollY);
  current = page;
  body.dataset.mobilePage = page;
  for (const tab of dock?.querySelectorAll('[data-mpager-tab]') || []) {
    if (tab.dataset.mpagerTab === page) tab.setAttribute('aria-current', 'true');
    else tab.removeAttribute('aria-current');
  }
  try { sessionStorage.setItem(STORAGE_KEY, page); } catch (_e) { /* private mode */ }
  // A fresh page opens at its own content, keeping the top chrome collapsed if
  // the player had already scrolled past it. A revisited page resumes.
  const saved = scrollByPage.get(page);
  const top = saved ?? Math.min(window.scrollY, contentTop());
  window.scrollTo({ top, behavior: 'instant' });
  document.dispatchEvent(new CustomEvent('mobile-pager:change', { detail: { page } }));
}

function animate(offsetFrom, offsetTo, opacityFrom, opacityTo, duration) {
  if (!main?.animate) return Promise.resolve();
  const animation = main.animate([
    { transform: `translateX(${offsetFrom}px)`, opacity: opacityFrom },
    { transform: `translateX(${offsetTo}px)`, opacity: opacityTo },
  ], { duration, easing: 'cubic-bezier(.2,.7,.25,1)', fill: 'forwards' });
  return animation.finished.catch(() => {}).then(() => animation);
}

function clearDrag() {
  if (!main) return;
  main.style.transform = '';
  main.style.opacity = '';
  main.style.willChange = '';
  main.getAnimations?.().forEach((animation) => {
    if (animation.effect?.target === main) animation.cancel();
  });
}

export function showPage(page, { from = 0 } = {}) {
  if (!PAGES.includes(page)) return;
  setTrayOpen(false);
  if (page === current) {
    if (from !== 0 && !reducedMotion.matches) {
      transition = animate(from, 0, 1, 1, 180).then(clearDrag).then(() => { transition = null; });
    } else clearDrag();
    return;
  }
  if (!phone.matches || reducedMotion.matches || !main?.animate) {
    clearDrag();
    applyPage(page);
    return;
  }
  const direction = PAGES.indexOf(page) > PAGES.indexOf(current) ? 1 : -1;
  const width = window.innerWidth;
  const run = async () => {
    await animate(from, -direction * width * 0.35, 1 - Math.min(1, Math.abs(from) / width) * 0.4, 0, 120);
    clearDrag();
    applyPage(page);
    await animate(direction * width * 0.35, 0, 0, 1, 190);
    clearDrag();
  };
  transition = (transition || Promise.resolve()).then(run).finally(() => { transition = null; });
}

function step(delta, from) {
  const next = PAGES[PAGES.indexOf(current) + delta];
  showPage(next || current, { from });
}

// Swipes that start inside something that owns horizontal motion stay there:
// range sliders, the Degenerette card carousel and salvage rows (touch-action
// pan-y), scratch surfaces (touch-action none), and any sideways scroller that
// actually overflows.
function blocksSwipe(target) {
  for (let el = target; el && el !== main && el.nodeType === 1; el = el.parentElement) {
    if (el.matches('input, select, textarea, [contenteditable], [data-no-page-swipe], [role="dialog"]')) return true;
    const style = getComputedStyle(el);
    const action = style.touchAction;
    if (action === 'none' || action === 'pan-y' || action === 'pinch-zoom') return true;
    if ((style.overflowX === 'auto' || style.overflowX === 'scroll')
      && el.scrollWidth > el.clientWidth + 1) return true;
  }
  return false;
}

let gesture = null;

function onTouchStart(event) {
  gesture = null;
  if (!phone.matches || event.touches.length !== 1 || body.dataset.mpagerTray === 'open') return;
  const touch = event.touches[0];
  if (touch.clientX < EDGE_GUARD_PX || touch.clientX > window.innerWidth - EDGE_GUARD_PX) return;
  if (blocksSwipe(event.target)) return;
  gesture = { x: touch.clientX, y: touch.clientY, t: event.timeStamp, axis: null, dx: 0 };
}

function onTouchMove(event) {
  if (!gesture || transition) return;
  const touch = event.touches[0];
  const dx = touch.clientX - gesture.x;
  const dy = touch.clientY - gesture.y;
  if (gesture.axis == null) {
    if (Math.hypot(dx, dy) < AXIS_LOCK_PX) return;
    gesture.axis = Math.abs(dx) > Math.abs(dy) * 1.2 ? 'x' : 'y';
    if (gesture.axis === 'x') main.style.willChange = 'transform';
  }
  if (gesture.axis !== 'x') return;
  if (event.cancelable) event.preventDefault();
  const atEdge = (dx > 0 && current === PAGES[0]) || (dx < 0 && current === PAGES.at(-1));
  gesture.dx = atEdge ? dx * EDGE_RESISTANCE : dx;
  gesture.lastT = event.timeStamp;
  main.style.transform = `translateX(${gesture.dx}px)`;
  main.style.opacity = String(1 - Math.min(0.35, Math.abs(gesture.dx) / window.innerWidth));
}

function onTouchEnd(event) {
  const done = gesture;
  gesture = null;
  if (!done || done.axis !== 'x') return;
  const elapsed = Math.max(1, (done.lastT ?? event.timeStamp) - done.t);
  const velocity = Math.abs(done.dx) / elapsed;
  const commit = Math.abs(done.dx) > window.innerWidth * COMMIT_FRACTION
    || (Math.abs(done.dx) > 40 && velocity > COMMIT_VELOCITY);
  main.style.transform = '';
  main.style.opacity = '';
  step(commit ? (done.dx < 0 ? 1 : -1) : 0, done.dx);
}

// Quest shortcuts and claim links call scrollIntoView on panels that may sit on
// another page. Switch to that page first so the native scroll has a target.
// Elements hidden by their own [hidden] state never pull the player away.
const nativeScrollIntoView = Element.prototype.scrollIntoView;
Element.prototype.scrollIntoView = function scrollIntoViewAcrossPages(...args) {
  if (phone.matches && !this.closest?.('[hidden]')) {
    const page = pageOf(this);
    if (page && page !== current) {
      clearDrag();
      setTrayOpen(false);
      applyPage(page);
    }
  }
  return nativeScrollIntoView.apply(this, args);
};

// ---- Condensed Pending ---------------------------------------------------

function setTrayOpen(open) {
  const next = Boolean(open) && phone.matches && pendingButton && !pendingButton.hidden;
  if ((body.dataset.mpagerTray === 'open') === next) return;
  if (next) body.dataset.mpagerTray = 'open';
  else delete body.dataset.mpagerTray;
  pendingButton?.setAttribute('aria-expanded', String(next));
  if (scrim) scrim.hidden = !next;
}

function renderPending(summary) {
  if (!pendingButton) return;
  const items = Array.isArray(summary?.items) ? summary.items : [];
  const rng = summary?.rng || null;
  const count = items.reduce((sum, item) => sum + (Number(item.count) || 1), 0);
  const ready = items.some((item) => item.state === 'ready') || rng?.requestable === true;
  pendingButton.hidden = items.length === 0 && !rng;
  pendingButton.dataset.state = ready ? 'ready'
    : items.some((item) => item.state === 'busy') ? 'busy' : 'waiting';
  const countNode = pendingButton.querySelector('[data-mpager-pending-count]');
  if (countNode) {
    countNode.textContent = String(count);
    countNode.hidden = count === 0;
  }
  const chips = pendingButton.querySelector('[data-mpager-pending-chips]');
  if (chips) {
    chips.textContent = '';
    // Group by kind + state so five luckboxes read as one chip.
    const groups = new Map();
    for (const item of items) {
      const key = `${item.label}|${item.state}`;
      const group = groups.get(key) || { ...item, count: 0 };
      group.count += Number(item.count) || 1;
      groups.set(key, group);
    }
    for (const group of groups.values()) {
      const chip = document.createElement('span');
      chip.className = 'mpager-chip';
      chip.dataset.state = group.state;
      chip.textContent = group.count > 1 ? `${group.label} ×${group.count}` : group.label;
      chips.appendChild(chip);
    }
  }
  const rngNode = pendingButton.querySelector('[data-mpager-pending-rng]');
  if (rngNode) {
    rngNode.hidden = !rng;
    rngNode.textContent = '';
    if (rng) {
      rngNode.dataset.phase = rng.phase;
      const label = document.createElement('span');
      label.textContent = rng.requestable ? 'RNG ▸' : 'RNG';
      rngNode.appendChild(label);
      for (let index = 0; index < (Number(rng.steps) || 5); index += 1) {
        const dot = document.createElement('i');
        if (index < (Number(rng.complete) || 0)) dot.className = 'is-complete';
        rngNode.appendChild(dot);
      }
    }
  }
  const parts = [];
  if (count > 0) parts.push(`${count} pending`);
  if (ready) parts.push('ready to open');
  if (rng?.status) parts.push(rng.status.toLowerCase());
  pendingButton.setAttribute('aria-label', `Pending actions: ${parts.join(', ') || 'none'}`);
  if (pendingButton.hidden) setTrayOpen(false);
}

// ---- Dock height ---------------------------------------------------------

function syncDockHeight() {
  const height = phone.matches && dock ? dock.getBoundingClientRect().height : 0;
  document.documentElement.style.setProperty('--mpager-dock-h', `${Math.ceil(height)}px`);
}

// ---- Wiring --------------------------------------------------------------

function init() {
  if (!main || !dock) return;
  let restored = null;
  try { restored = sessionStorage.getItem(STORAGE_KEY); } catch (_e) { /* private mode */ }
  if (restored && restored !== current && PAGES.includes(restored)) applyPage(restored);
  dock.addEventListener('click', (event) => {
    const tab = event.target.closest?.('[data-mpager-tab]');
    if (tab) {
      if (tab.dataset.mpagerTab === current) {
        setTrayOpen(false);
        window.scrollTo({ top: Math.min(window.scrollY, contentTop()), behavior: 'smooth' });
      } else showPage(tab.dataset.mpagerTab);
      return;
    }
    if (event.target.closest?.('[data-mpager-pending]')) {
      setTrayOpen(body.dataset.mpagerTray !== 'open');
    }
  });
  scrim?.addEventListener('click', () => setTrayOpen(false));
  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape' && body.dataset.mpagerTray === 'open') setTrayOpen(false);
  });
  main.addEventListener('touchstart', onTouchStart, { passive: true });
  main.addEventListener('touchmove', onTouchMove, { passive: false });
  main.addEventListener('touchend', onTouchEnd, { passive: true });
  main.addEventListener('touchcancel', () => {
    gesture = null;
    clearDrag();
  }, { passive: true });

  document.addEventListener('app-reveal-tray:summary', (event) => renderPending(event.detail));
  const tray = document.querySelector('app-reveal-tray');
  if (tray?.pendingSummary) renderPending(tray.pendingSummary);
  // Opening a reveal from the sheet hands the screen to the overlay; close
  // the sheet behind it so the player lands back on their page.
  document.addEventListener('click', (event) => {
    if (body.dataset.mpagerTray !== 'open') return;
    if (event.target.closest?.('.rrt-action:not(.rrt-action--inspectable)')) {
      setTimeout(() => setTrayOpen(false), 0);
    }
  });

  if (typeof ResizeObserver === 'function') new ResizeObserver(syncDockHeight).observe(dock);
  phone.addEventListener?.('change', () => {
    gesture = null;
    clearDrag();
    setTrayOpen(false);
    syncDockHeight();
  });
  syncDockHeight();
}

init();
